"""Buildless static export: no private service, credential or management address."""
from pathlib import Path
import html,json
ROOT=Path(__file__).resolve().parents[1]
NAV=[('index.html','Обзор'),('architecture.html','Устройство сети'),('experiments.html','Эксперименты'),('rfcs.html','RFC'),('publications.html','Публикации'),('participate.html','Участвовать')]
REPO='https://github.com/relcom-technologies/ipvx-research'
def layout(file,title,body):
 nav=''.join(f'<a href="{href}"'+(' aria-current="page"' if href==file else '')+'>'+name+'</a>' for href,name in NAV)
 return f'''<!doctype html><html lang="ru"><head><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1"><meta name="description" content="Исследования IPvX: нативная сеть для агентов, воспроизводимые эксперименты и совместная разработка RFC."><meta name="theme-color" content="#f7f6f2"><title>{title} · IPvX Research</title><link rel="icon" href="assets/favicon.svg" type="image/svg+xml"><link rel="stylesheet" href="assets/portal.css"><script src="assets/portal.js" defer></script></head><body><a class="skip" href="#main">К содержимому</a><header><a class="wordmark" href="index.html">IPvX<span>Research</span></a><nav aria-label="Разделы">{nav}</nav><a class="source-link" href="{REPO}">GitHub ↗</a></header><main id="main">{body}</main><footer><a class="wordmark" href="index.html">IPvX<span>Research</span></a><p>Исследуем. Измеряем. Обсуждаем RFC.</p><div><a href="governance.html">Правила участия</a><a href="reproduce.html">Воспроизвести</a><a href="data/provenance.json">Происхождение данных</a></div><p class="small">Экспериментальный проект · один оператор инфраструктуры · снимок данных 27 октября 2026. Этот публичный веб-портал работает через обычные IP, DNS и HTTPS.</p></footer></body></html>'''
def heading(title,lead):return f'<div class="page-title"><h1>{title}</h1><p class="lead">{lead}</p></div>'
def article(title,text):return f'<section class="prose"><h2>{title}</h2>{text}</section>'
def trace():return '''<div class="trace" data-ui><div class="trace-heading"><h2>От мысли до сообщения</h2><span class="badge">Объяснение протокола</span></div><p>Модель работает на своей машине. По сети уходят зашифрованная задача и результат.</p><svg viewBox="0 0 720 185" role="img" aria-label="Агент A через маршрутизатор R1 отправляет задачу агенту B"><defs><marker id="arrow" markerWidth="8" markerHeight="8" refX="7" refY="4" orient="auto"><path d="M0 0L8 4L0 8" fill="currentColor"/></marker></defs><path class="edge" d="M188 85H279M434 85H525" marker-end="url(#arrow)"/><g><rect x="14" y="25" width="174" height="120" rx="8"/><text x="34" y="61" class="node-title">Агент A</text><text x="34" y="86">Локальная модель</text><text x="34" y="115" class="id">ID: public-key hash</text></g><g><rect x="284" y="43" width="150" height="84" rx="8"/><text x="304" y="78" class="node-title">Посредник R1</text><text x="304" y="104">Следующий сосед</text></g><g><rect x="530" y="25" width="174" height="120" rx="8"/><text x="550" y="61" class="node-title">Агент B</text><text x="550" y="86">Своя модель</text><text x="550" y="115" class="id">ID: public-key hash</text></g><text x="198" y="166">Ethernet · 0x88B5 · без IP и DNS в доставке</text></svg><div class="trace-mobile" aria-label="Маршрут A через R1 к B"><div><strong>Агент A</strong><span>Локальная модель · устойчивый ID</span></div><p>↓ Кадры Ethernet 0x88B5</p><div><strong>Посредник R1</strong><span>Выбирает следующего соседа</span></div><p>↓ Без IP и DNS в доставке</p><div><strong>Агент B</strong><span>Своя модель · свой ID</span></div></div><div class="trace-controls" role="group" aria-label="Этапы обмена"><button type="button" data-step="0" aria-pressed="true">1. Сформировать</button><button type="button" data-step="1" aria-pressed="false">2. Передать</button><button type="button" data-step="2" aria-pressed="false">3. Выполнить</button><button type="button" data-step="3" aria-pressed="false">4. Ответить</button></div><div id="trace-detail" aria-live="polite"><h3>Агент A формирует задачу</h3><p>Получатель — устойчивый ID. Сообщение получает подпись, срок действия и уникальный номер; содержимое шифруется для B.</p></div><p class="small">Это интерактивное объяснение, а не живой сетевой обмен. Фактические журналы — в экспериментах.</p></div>'''
def rfc_rows():
 titles=['Идентичность и сообщения','Локальная маршрутизация','Участие и большинство','Оценка моделей и сети']
 return ''.join(f'<a class="record" href="rfc-{i:04d}.html"><span class="mono">RFC-{i:04d}</span><strong>{t}</strong><span class="badge">Черновик</span><span aria-hidden="true">↗</span></a>' for i,t in enumerate(titles,1))
body='''<div class="board"><section class="name-cell"><h1>IPvX. Сеть для агентов</h1><p class="lead">Исследуем адресацию и доставку сообщений, которые агенты могут использовать напрямую. Разрабатываем RFC и проверяем идеи на работающем стенде.</p><a class="button" href="rfcs.html">Открыть проекты RFC</a></section><aside class="scope-cell"><h2>Что уже есть</h2><p>Собственный Ethernet-протокол, устойчивые ID и локальный выбор маршрута.</p><p>Пять ВМ в одной инфраструктуре. Глобальная сеть и открытый допуск пока не доказаны.</p><a href="experiments.html">Посмотреть доказательства →</a></aside><div class="rail"><a href="architecture.html">Как доставляется пакет →</a><a href="experiments.html">Что показали опыты →</a><a href="rfcs.html">Что обсуждаем в RFC →</a><a href="participate.html">Как внести вклад →</a></div><section class="mechanism-cell">'''+trace()+'''</section><aside class="rfc-cell"><h2>Разработка открыта для обсуждения</h2><p>Предложите исследование, изменение протокола или свою модель.</p><p>Допуск и принятие вклада — после одобрения большинством действующего состава. Сейчас проект находится в начальной фазе: один участник с правом голоса.</p><a class="button secondary" href="participate.html">Предложить участие</a><a href="governance.html">Как считаются голоса →</a></aside></div><section class="section"><div class="section-intro"><h2>От идеи к проверке</h2><p>Каждый результат имеет границы. Расчётная модель, настоящий сетевой обмен и ответы языковой модели публикуются отдельно.</p></div><div class="experiment-rows"><a href="experiments.html#native"><strong>Пять машин, два маршрута</strong><span>Нативный обмен и перестроение пути</span><span class="badge pass">Измерено</span></a><a href="experiments.html#documents"><strong>384 задачи с документами</strong><span>16 процессов на одной машине; без LLM</span><span class="badge pass">Измерено</span></a><a href="experiments.html#llm"><strong>Две модели, общая задача</strong><span>IPvX, прямой IP и IP через посредника</span><span class="badge" id="llm-home-status">Проверка идёт</span></a><a href="experiments.html#scale"><strong>До 256 маршрутизаторов</strong><span>Расчёт с ещё не реализованными допущениями</span><span class="badge">Моделирование</span></a></div></section><section class="section"><div class="section-intro"><h2>Протокол пишется вместе</h2><p>RFC — рабочие документы проекта. Их номера не означают публикацию в IETF или принятие стандарта.</p></div>'''+rfc_rows()+'''</section>'''
(ROOT/'index.html').write_text(layout('index.html','Исследуем сеть для агентов',body))
arch=heading('Как устроена сеть','Стабильный ID отвечает на вопрос «кому». Локальный маршрут — «через какого соседа». Физический канал — «как передать кадр».')+trace()
arch+=article('Четыре разных уровня','''<ol class="stages"><li><h3>Идентичность</h3><p>Узел сам создаёт ключи. Его ID вычисляется из открытого ключа и сохраняется при смене сетевого положения. Доверие и допуск задаются отдельно.</p></li><li><h3>Задача</h3><p>Агенты обмениваются структурированными заданиями, доказательствами и результатами. Для этого им не нужны страницы сайтов. Совместимость форматов задач всё равно необходима.</p></li><li><h3>Маршрутизация</h3><p>Узел получает подписанные объявления соседей и выбирает следующий переход из локальной таблицы. Центральный наблюдатель не передаёт задания и не назначает маршруты.</p></li><li><h3>Доставка</h3><p>В нативном опыте пакет превращается в кадры Ethernet с EtherType 0x88B5. MAC обозначает соседа на локальном канале; ID обозначает конечного агента.</p></li></ol>''')
arch+=article('Где остаётся IP','''<p>Управление машинами, установка моделей и этот сайт используют существующий Интернет. Нативные задания и объявления маршрутов в эксперименте идут отдельным протоколом. Это проверка собственного уровня доставки в контролируемом Ethernet-сегменте.</p><p>Для связи независимых площадок нужны физические каналы или явно обозначенная подложка. Если соединить площадки IP-туннелем, это будет IPvX поверх IP. Такой вариант может быть полезен, но он не докажет отказ от IP в нижележащей сети.</p>''')
arch+=article('Что берём из IPvX','''<p>Самостоятельное создание идентификаторов, отделение личности от местоположения, проверяемые контакты и распределённое разрешение. К ним добавляем явный допуск, границы ресурсов и измеримую доставку. Человеческие удобные имена остаются необязательными псевдонимами, а не корнем доверия.</p><p><a href="rfc-0002.html">Открыть черновик маршрутизации →</a></p>''')
(ROOT/'architecture.html').write_text(layout('architecture.html','Устройство сети',arch))
exp=heading('Эксперименты и результаты','Показываем, что именно запускали, что измерили и какой вывод эти данные допускают.')
exp+='''<section class="section" id="llm"><div class="section-intro"><h2>Две локальные модели</h2><p>Qwen3-0.6B Q8_0 на разных машинах. A пишет черновик, B проверяет его по дополнительным фактам, A делает итоговый вывод. Три варианта доставки, одинаковые вопросы и параметры моделей.</p></div><div id="llm-report" class="result-panel"><p>Запуск сравнения продолжается. Числа будут опубликованы после завершения и проверки журналов.</p></div><div id="llm-transcript"></div><p><a href="data/llm-protocol.txt">Предварительно зафиксированный протокол</a> · <a href="rfc-0004.html">Методика оценки</a></p></section>'''
exp+='''<section class="section" id="native"><h2>Пять машин и отказ посредника</h2><div class="facts"><div><strong>A → R1 → B</strong><span>Основной путь</span></div><div><strong>A → R2 → R3 → B</strong><span>Запасной путь</span></div></div><p class="measure">Задания и управление маршрутами — кадры 0x88B5. Прямой обмен A–B запрещён в стенде. Маршрут меняется после закрытия сокета R1; это не отключение питания ВМ.</p><p>Проверены подписанные переходы, сохранение ID, запрет прямого пути и автоматическое возвращение R1. Один оператор, один дата-центр, фиксированный состав участников. Контроль машин остаётся на IP.</p></section>'''
exp+='''<section class="section" id="documents"><h2>Документы через нативную сеть</h2><div class="facts"><div><strong>384 / 384</strong><span>Задачи дали ожидаемый результат</span></div><div><strong>16 процессов</strong><span>Одна физическая машина</span></div><div><strong>1 321 мс</strong><span>p95 времени задачи</span></div></div><p class="measure">Индексация текстов IPvX, точный поиск и SHA-256. По 128 задач каждого вида. 80 повторных попыток, 23 намеренных повтора запросов, 384 уникальных выполнения.</p><p>Сокет одного узла был закрыт на 10 044 мс. После обнаружения отказа 93 корректные доставки прошли во время отключения; семь затронутых путей перестроились. Это программные процессы с собственными ключами, а не языковые модели.</p><p><a href="data/native-summary.json">Скачать сводку с происхождением данных →</a></p></section>'''
exp+='''<section class="section" id="scale"><h2>Расчёт больших сетей</h2><p class="lead">16, 64 и 256 маршрутизаторов; до 2 048 логических агентов.</p><p class="measure">Это дискретная модель очередей, потерь и отказов. Компактные объявления и увеличенный бюджет переходов предполагаются в модели, но ещё не реализованы в текущем протоколе.</p><p>36 прогонов по 12 000 предлагаемых задач. Для 256 маршрутизаторов: около 99,8% доставки в штатном сценарии и около 79% при перегрузке в заданных условиях. Параметры не откалиброваны по Интернету и не являются сравнением с IP.</p><p>Следующий этап — реализовать контроль перегрузки и измерить состояние маршрутов до увеличения сети. <a href="data/scale-summary.json">Параметры модели →</a></p></section>'''
(ROOT/'experiments.html').write_text(layout('experiments.html','Эксперименты',exp))
(ROOT/'rfcs.html').write_text(layout('rfcs.html','Проекты RFC',heading('Совместная разработка RFC','Обсуждаем устройство протокола через конкретные предложения, проверяемые критерии и открытые решения.')+rfc_rows()+article('Как меняется документ',f'<p>Черновик → предложение изменения → обсуждение → голосование → проверка реализации → принятая версия. Сейчас все четыре документа — черновики. Нет ни одного принятого стандарта.</p><a class="button" href="{REPO}/issues/new?template=proposal.yml">Предложить RFC или изменение</a>')+article('RFC проекта и RFC IETF','<p>Локальная нумерация помогает обсуждать тексты и их версии. Она не означает присвоения номера RFC Editor, одобрения IETF или совместимости с промышленными протоколами.</p>')))
pub=heading('Публикации и материалы','Исходные идеи, текущие протоколы и воспроизводимые результаты — с прямыми ссылками на источники.')
pub+=f'''<a class="publication" href="https://archive.org/details/ipv-x-ecosystem_202405/IPvX_Ecosystem.pdf"><h2>IPvX Ecosystem</h2><p>Исходная концепция экосистемы IPvX. Публикация на Internet Archive.</p><span>Открыть документ ↗</span></a><a class="publication" href="https://archive.org/details/rapid-distributed-ipv-x-resolver/Rapid+distributed+IPvX+resolver"><h2>Rapid distributed IPvX resolver</h2><p>Распределённое разрешение идентификаторов. Исходный исследовательский материал.</p><span>Открыть материал ↗</span></a><a class="publication" href="https://github.com/relcom-technologies/IPvX_resolver"><h2>IPvX resolver</h2><p>Существующая реализация резолвера. Это отдельная работа; она не равна новой нативной сети или готовому глобальному протоколу.</p><span>Репозиторий ↗</span></a><a class="publication" href="{REPO}/tree/main/rfc"><h2>Рабочие документы исследований</h2><p>Четыре проекта RFC, история изменений и обсуждения.</p><span>Исходные тексты ↗</span></a>'''
(ROOT/'publications.html').write_text(layout('publications.html','Публикации',pub))
join=heading('Присоединиться к исследованию','Предложите задачу, модель или изменение протокола. Обсудим результат, условия воспроизведения и необходимый допуск.')
join+=f'''<div class="join-grid"><section><h2>Подготовить предложение</h2><p>Форма составит публичную заявку в GitHub. Ничего не отправится до вашего действия в GitHub. Не указывайте закрытые данные и секреты.</p><form id="join-form"><label for="kind">Что вы предлагаете</label><select id="kind" name="kind"><option>Свою модель</option><option>Эксперимент</option><option>Проект RFC</option><option>Изменение состава</option></select><label for="proposal-title">Короткое название</label><input id="proposal-title" name="title" required maxlength="120" placeholder="Например: повторить опыт с локальной моделью"><label for="proposal-body">Цель и способ проверки</label><textarea id="proposal-body" name="body" rows="6" required maxlength="4000" placeholder="Версия модели, лицензия, необходимые ресурсы, задача и ожидаемые измерения"></textarea><button class="button" type="submit">Открыть заявку в GitHub</button><p id="join-feedback" role="status"></p></form><noscript><a href="{REPO}/issues/new?template=proposal.yml">Создать предложение в GitHub</a></noscript></section><aside><h2>Что произойдёт дальше</h2><ol class="join-steps"><li>Публичное обсуждение и уточнение воспроизводимости.</li><li>Голосование действующего состава: больше половины всех допущенных участников.</li><li>Проверка лицензии, ресурсов и изоляции модели.</li><li>Отдельный согласованный запуск и публикация результата.</li></ol><p>Поддержка произвольных внешних endpoint и автоматическая выдача сетевого доступа пока не реализованы. Свою модель можно предложить как локальные веса, адаптер или воспроизводимый пакет.</p><a href="governance.html">Правила допуска и начальный состав →</a></aside></div>'''
(ROOT/'participate.html').write_text(layout('participate.html','Участвовать',join))
gov=heading('Как принимаются решения','Одобрение большинства обязательно для допуска вклада. Автоматическое подключение неизвестной модели к машинам стенда не выполняется.')
gov+=article('Текущий состав','<p><strong>1 участник с правом голоса: ashkitt, владелец проекта.</strong> Порог сейчас — один голос. Это начальная фаза, а не подтверждение независимого сообщества. Изменение состава тоже проходит предложение и большинство.</p><p><a href="governance.json">Машиночитаемый состав и параметры →</a></p>')
gov+=article('Голосование',f'<p>Участник с правом голоса оставляет в предложении комментарий <code>/vote yes</code>, <code>/vote no</code> или <code>/vote abstain</code>. Учитывается последний допустимый голос каждого человека. Боты и модели голосов не получают.</p><p>Предлагаемая начальная процедура: 72 часа, без досрочного принятия; нужно больше половины всего состава на момент открытия предложения. Эти детали вынесены на обсуждение в RFC-0003. Историю голосов можно проверить в GitHub.</p><p>Автоматическая метка сообщает результат подсчёта. Она не объединяет код и не выдаёт ключи. Принятие изменения и подключение выполняются отдельным проверяемым действием.</p><a href="{REPO}/issues?q=is%3Aissue+label%3Aproposal">Обсуждения и голоса ↗</a>')
gov+=article('Границы первой версии','<p>Апелляции, конфликт интересов, неактивные участники, финансирование и независимые площадки требуют дальнейшего решения. Правила нельзя считать утверждёнными сообществом, которого ещё нет. Все RFC пока имеют статус черновика.</p><a href="rfc-0003.html">Полный проект порядка участия →</a>')
(ROOT/'governance.html').write_text(layout('governance.html','Правила участия',gov))
